import{_ as s,o as e,c as t,a2 as i}from"./chunks/framework.BvlN9b-o.js";const g=JSON.parse('{"title":"发布自己的文档站点","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/getting-started/publish-docs","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"getting-started/publish-docs.md","filePath":"getting-started/publish-docs.md"}'),d={name:"getting-started/publish-docs.md"};function o(n,a,p,r,c,h){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="发布自己的文档站点" tabindex="-1">发布自己的文档站点 <a class="header-anchor" href="#发布自己的文档站点" aria-label="Permalink to &quot;发布自己的文档站点&quot;">​</a></h1><p>把已构建并检查的双语静态站点发布到自己的 GitHub Pages。仓库 Markdown、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/site.json" target="_blank" rel="noreferrer">site.json</a>和实际代码是来源；<code>apps/docs/.generated</code> 与 dist 不提交到源码分支。编写和登记页面见<a href="./../guides/documentation">维护文档</a>。</p><p>本指南需要仓库推送权限，首次设置还需要仓库管理权限。请求 Pages 构建需要已安装并登录的 GitHub CLI。命令在仓库根目录运行；发布命令会向远端 <code>gh-pages</code> 写入静态产物。</p><h2 id="准备公开来源与构建" tabindex="-1">准备公开来源与构建 <a class="header-anchor" href="#准备公开来源与构建" aria-label="Permalink to &quot;准备公开来源与构建&quot;">​</a></h2><p>确认 <code>origin</code> 指向自己的 GitHub 仓库，并把 <code>docs/site.json.repository</code> 改为 <code>owner/repository</code>。完成双语页面登记、保存并推送源码，再构建：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>站点页脚 SHA 表示本次构建引用的源码版本，不代表每个示例命令都在该版本通过。需要发布的内容必须在对应提交中；提交后重新构建，让源码链接能在 GitHub 读取。</p><p>默认 Pages 子路径由仓库名决定。非默认部署路径可以在构建时指定：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DOCS_BASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/my-saas/</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>base 必须和实际部署路径一致。生成后的章节、语言切换、静态资产和搜索使用同一 base；不要靠修改 dist 修复路径。</p><h2 id="首次发布并设置-pages" tabindex="-1">首次发布并设置 Pages <a class="header-anchor" href="#首次发布并设置-pages" aria-label="Permalink to &quot;首次发布并设置 Pages&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/publish-docs.mjs</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/scripts/publish-docs.mjs" target="_blank" rel="noreferrer">发布脚本</a>检查 dist 的仓库/源码版本与当前发布输入一致，将产物提交并推送至独立 <code>gh-pages</code>，不切换当前源码分支或修改其暂存区。重复发布相同产物不会创建无意义的提交。</p><p>在 GitHub <strong>Settings → Pages → Build and deployment</strong> 选择 <strong>Deploy from a branch</strong>，分支 <code>gh-pages</code>、目录 <code>/ (root)</code> 并保存。仓库可见性是否支持 Pages 取决于账号方案。</p><p>然后请求构建并验证在线内容：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/publish-docs.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --request-build</span></span></code></pre></div><p>命令检查 Pages 设置，显式请求构建，确认构建对应刚发布的静态提交，再读取线上首页的源码 SHA；五分钟内未成功就失败退出。远端分支推送成功不等于页面已经上线。</p><h2 id="后续自动发布" tabindex="-1">后续自动发布 <a class="header-anchor" href="#后续自动发布" aria-label="Permalink to &quot;后续自动发布&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/.github/workflows/ci.yml" target="_blank" rel="noreferrer">CI</a>按变更路径选择检查：文档运行 tooling 与 documentation，教学源码运行后端课程，客户端改动运行相关客户端检查。<code>verify</code> 汇总所有被选中任务，失败或意外跳过都会阻止通过。documentation 任务保存已检查的网站产物；合入 <code>main</code> 且 <code>verify</code> 与 documentation 都成功后，发布任务推送同一份产物到 <code>gh-pages</code>，再使用 <code>contents: write</code> 与 <code>pages: write</code> 显式请求 Pages 构建。没有网站产物的提交不会触发文档发布。</p><p>GitHub Actions 的 <code>GITHUB_TOKEN</code> 推送不会自动触发 Pages 构建，因此不能省略 <code>--request-build</code>。管理员的一次性 Pages 设置不会由发布任务隐式修改。</p><h2 id="验证与失败恢复" tabindex="-1">验证与失败恢复 <a class="header-anchor" href="#验证与失败恢复" aria-label="Permalink to &quot;验证与失败恢复&quot;">​</a></h2><p>打开 <code>https://&lt;owner&gt;.github.io/&lt;repository&gt;/</code>，检查中英文同页切换、搜索、自己的新章节、源码版本与源码链接。修改 base 或导航时，先用 <code>just e2e-docs</code> 在静态产物上验证；不需要 API、数据库或 Electron。</p><table tabindex="0"><thead><tr><th>失败</th><th>处理</th></tr></thead><tbody><tr><td>artifact 与仓库/版本不一致</td><td>确认 repository/origin 与目标提交，重新构建</td></tr><tr><td>Pages 设置不匹配</td><td>使用 <code>gh-pages:/</code> 的 branch 发布方式，重新请求</td></tr><tr><td>权限或构建失败</td><td>核对 GitHub CLI/CI 权限和 Pages 错误；保留失败输出</td></tr><tr><td>页面/资源 404</td><td>核对实际路径与 DOCS_BASE，修复来源后重建发布</td></tr><tr><td>需要回到旧内容</td><td>检出已审阅旧版本后重新构建发布，不手工修改静态页面</td></tr></tbody></table><p>发布自己的后端产品说明时，从<a href="./../tutorials/public-site">静态站点维护</a>增加已交付能力的入口；业务 API 的部署与恢复另见<a href="./../tutorials/single-machine-production">生产指南</a>。</p><hr><p>源码版本：<code>e87f840d6dfc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/getting-started/publish-docs.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,26)])])}const b=s(d,[["render",o]]);export{g as __pageData,b as default};
